PROGRAM ST140_VERKTYGSBYTE
VAR
    steg        : INT := 0;
    onskatVerkt : INT := 1;
    trigDone    : R_TRIG;
    tmrLas      : TON;
    xDriftsklar : BOOL := FALSE;
    xLasFel     : BOOL := FALSE;
END_VAR

trigDone(CLK := ST140_RB_DONE);

IF trigDone.Q THEN
    IF onskatVerkt = 1 THEN
        onskatVerkt := 2;
    ELSE
        onskatVerkt := 1;
    END_IF;
END_IF;

tmrLas(IN := (steg = 3), PT := T#3s);
IF tmrLas.Q AND NOT ST140_TCH_LOCKED THEN
    xLasFel := TRUE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND NOT xLasFel;

IF NOT xDriftsklar THEN
    ST140_RB_START := FALSE;
    ST140_TCH_BUSY := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST140_RB_START := FALSE;
            IF ST140_TOOL_ID = onskatVerkt AND ST140_TCH_LOCKED THEN
                ST140_TCH_BUSY := FALSE;
                ST140_TCH_LOCK := TRUE;
                steg := 10;
            ELSIF ST140_TOOL_ID <> 0 AND ST140_TOOL_ID <> onskatVerkt THEN
                ST140_TCH_BUSY := TRUE;
                steg := 1;
            ELSIF ST140_TOOL_ID = 0 THEN
                ST140_TCH_BUSY := TRUE;
                steg := 2;
            END_IF;

        1:
            ST140_RB_START := FALSE;
            ST140_TCH_BUSY := TRUE;
            IF ST140_RCK_PRS1 OR ST140_RCK_PRS2 THEN
                ST140_TCH_LOCK := FALSE;
            END_IF;
            IF ST140_TCH_UNLOCKED THEN
                steg := 2;
            END_IF;

        2:
            ST140_RB_START := FALSE;
            ST140_TCH_BUSY := TRUE;
            ST140_TCH_LOCK := FALSE;
            IF (onskatVerkt = 1 AND ST140_RCK_PRS1) OR (onskatVerkt = 2 AND ST140_RCK_PRS2) THEN
                steg := 3;
            END_IF;

        3:
            ST140_RB_START := FALSE;
            ST140_TCH_BUSY := TRUE;
            ST140_TCH_LOCK := TRUE;
            IF ST140_TCH_LOCKED AND (ST140_TOOL_ID = onskatVerkt) AND (ST140_TOOL_ID = 1 OR ST140_TOOL_ID = 2) THEN
                ST140_TCH_BUSY := FALSE;
                steg := 10;
            END_IF;

        10:
            ST140_TCH_BUSY := FALSE;
            IF ST140_RB_DONE THEN
                ST140_RB_START := FALSE;
                steg := 0;
            ELSIF ST140_TCH_LOCKED AND (ST140_TOOL_ID = onskatVerkt) AND (ST140_TOOL_ID = 1 OR ST140_TOOL_ID = 2) THEN
                ST140_RB_START := TRUE;
                ST140_TCH_LOCK := TRUE;
            ELSE
                ST140_RB_START := FALSE;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

