PROGRAM ST140_VERKTYGSBYTE_TRASIG
VAR
    steg : INT := 0;
END_VAR

IF EMG_OK AND AIR_OK THEN
    IF ST140_TCH_LOCKED THEN
        ST140_RB_START := TRUE;
        ST140_TCH_BUSY := FALSE;
        ST140_TCH_LOCK := TRUE;
    ELSE
        ST140_RB_START := FALSE;
        ST140_TCH_BUSY := TRUE;
        ST140_TCH_LOCK := TRUE;
    END_IF;
ELSE
    ST140_RB_START := FALSE;
    ST140_TCH_BUSY := FALSE;
    ST140_TCH_LOCK := FALSE;
END_IF;
END_PROGRAM
